import {CommonMemoryProjectsPanel} from '../../../src/CommonMemoryProjectsPanel';
import {CommonMemoryFollowupNotice} from '../../../src/CommonMemoryFollowupNotice';
import React,{useState,useMemo} from 'react';
import {RemoteCommonMemoryPanel} from '../../../src/RemoteCommonMemoryPanel';
import {RemoteMetaCommonMemoryCloudHint} from '../../../src/RemoteMetaCommonMemoryCloudHint';
import type {MobileWorkspaceRequest,MobileWorkspaceResult} from '../../../src/mobileWorkspaceProtocol';
import {createRoot} from 'react-dom/client';
import {CommonMemoryPanel,ProjectCommonMemoryChoice} from '../../../src/CommonMemoryPanel';
import {A,B,C} from './cloud';
import {createCommonMemoryClient,commonMemoryHttpTransport} from '../../../src/commonMemoryClient';
const client=createCommonMemoryClient(commonMemoryHttpTransport());
/** ?focus-memory=<memoryId> / ?focus-group=<groupId>: the jump props a project's memory tab passes. */
const params=new URLSearchParams(location.search),focus={memoryId:params.get('focus-memory')??undefined,groupId:params.get('focus-group')??undefined};
function Fixture(){const [projectTools,setProjectTools]=useState<string|null>(null);const [goal,setGoal]=useState(''),[ids,setIds]=useState<string[]>([]),[draft,setDraft]=useState<{title:string;prompt:string}|null>(null),[reveal,setReveal]=useState(0);if(projectTools)return <main><button className="min-h-11" onClick={()=>setProjectTools(null)}>기억 시험 화면으로 돌아가기</button><CommonMemoryProjectsPanel client={client} groupId={projectTools}/></main>;return <main style={{maxWidth:1100,margin:'24px auto',padding:20}}><h1>공통기억 · 실제 컴포넌트 / 격리된 클라우드 테스트</h1><CommonMemoryFollowupNotice client={client} onOpen={()=>setReveal(v=>v+1)}/><>{draft?<section data-testid="common-memory-workroom-draft"><h2>{draft.title}</h2><pre>{draft.prompt}</pre><button className="min-h-11" onClick={()=>setDraft(null)}>공통기억으로 돌아가기</button></section>:<CommonMemoryPanel key={reveal} initiallyOpen={reveal>0||!!focus.memoryId||!!focus.groupId} focusMemoryId={focus.memoryId} focusGroupId={focus.groupId} workroom={{targetId:new URLSearchParams(location.search).has("no-ops")?undefined:"fixture-ops",open:(_target,title,prompt)=>setDraft({title,prompt})}} activeProjects={[{portId:"recent-fixture",name:"최근 사용 프로젝트",lastUsedAt:1000}]} client={client} onOpenOps={()=>{document.title='opened:ops';}} onOpenCloudSettings={()=>{document.title='opened:cloud-settings';}} memories={[{memoryId:A,name:'원본 A'},{memoryId:B,name:'원본 B'},{memoryId:C,name:'원본 C'}]}/>}</><h2>새 프로젝트 시작</h2><ProjectCommonMemoryChoice client={client} goal={goal} onGoalChange={setGoal} selectedIds={ids} onSelectedIdsChange={setIds}/><output data-testid="selection-count">선택한 공통기억: {ids.length}</output><button className="min-h-11" onClick={()=>{void fetch("/fixture/stats").then(r=>r.json()).then(r=>setProjectTools(r.groups.at(-1).state.id));}}>별도 프로젝트 가져오기 시험 화면</button></main>;}
/** ?phone=1: the phone's panel over the real encrypted-RPC host chunking (no relay), with a tab switch that unmounts it.
 *  &ops=1 hands it an OPS workroom whose open() only records the draft and moves to the other tab, as the portal fills the
 *  workroom composer; 「다른 Mac 연결」 remounts it under a new connection key, as the portal keys it per controller. */
function Phone(){const [tab,setTab]=useState<'common'|'other'>('common');const rpcV2=new URLSearchParams(location.search).has('v2');const [connection,setConnection]=useState(1),[draft,setDraft]=useState<{targetId:string;title:string;prompt:string}|null>(null),[focusMemory,setFocusMemory]=useState(focus.memoryId);
 const transport=useMemo(()=>async(request:MobileWorkspaceRequest):Promise<MobileWorkspaceResult>=>{const response=await fetch('/fixture/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(request)});const result=await response.json();if(!response.ok)throw Error(result.error);return result;},[]);
 const workroom=useMemo(()=>params.has('ops')?{targetId:'fixture-ops',open:(targetId:string,title:string,prompt:string)=>{setDraft({targetId,title,prompt});setTab('other');}}:undefined,[]);
 return <main style={{maxWidth:430,margin:'0 auto',padding:12}}><nav style={{display:'flex',gap:8,flexWrap:'wrap'}}><button className="min-h-11" onClick={()=>setTab('common')}>공통기억 탭</button><button className="min-h-11" onClick={()=>setTab('other')}>다른 탭</button><button className="min-h-11" onClick={()=>setConnection(n=>n+1)}>다른 Mac 연결</button><button className="min-h-11" onClick={()=>{setFocusMemory(A);setTab('common');}}>등록 A의 공통기억</button></nav>{draft&&<section data-testid="phone-workroom-draft" hidden={tab!=='other'}><h2>{draft.title}</h2><p>{draft.targetId}</p><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{draft.prompt}</pre></section>}<RemoteCommonMemoryPanel key={connection} visible={tab==='common'} available online hostName="시험 Mac" cacheKey={'fixture-connection-'+connection} rpcV2={rpcV2} transport={transport} workroom={workroom} focusMemoryId={focusMemory} onFocusHandled={()=>setFocusMemory(undefined)}/></main>;}
/** ?local-hint=1: the phone's '이전 로컬 기억' on a Mac whose local list is empty, so the cloud-tab hint is up. */
function LocalHint(){const request=useMemo(()=>async(body:Record<string,unknown>)=>body.operation==='list'?{memories:[],nextOffset:null,total:0}:{projects:[],nextOffset:null,total:0},[]);return <main style={{maxWidth:430,margin:'0 auto',padding:12}}><section className="meta-common-memory-mobile"><RemoteMetaCommonMemoryCloudHint visible remote hostName="시험 Mac" request={request as any}/></section></main>;}
createRoot(document.getElementById('root')!).render(params.has('project-tools')?<CommonMemoryProjectsPanel client={client} groupId={params.get('project-tools')!}/>:params.has('local-hint')?<LocalHint/>:new URLSearchParams(location.search).has('phone')?<Phone/>:<Fixture/>);
